def watch(n,en,ro,why,whyro,refs,desc,descro,kind='qualitative',basis='analytical_test',period='Q2 FY2027',**kw):
 c=dict(kind=kind,basis=basis,description=B(desc,descro),rationale=B(why,whyro),**kw)
 if basis!='analytical_test':c['evidence_refs']=refs
